using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
internal class CommandScript:IRunCommand{
Material Make(string name,string tex,bool alpha){string dir="Assets/Materials/VisualRefinement";Directory.CreateDirectory(dir);string path=dir+"/"+name+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m)return m;m=new Material(Shader.Find("Standard"));m.name=name;m.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/TerrainDemoScene_HDRP/Prefabs/Trees/Pines/Pine_A/Textures/"+tex+"_Color.png");if(!m.mainTexture)throw new Exception("texture missing");m.enableInstancing=true;m.SetFloat("_Glossiness",.06f);if(alpha){m.SetFloat("_Mode",1);m.SetFloat("_Cutoff",.33f);m.EnableKeyword("_ALPHATEST_ON");m.SetOverrideTag("RenderType","TransparentCutout");m.renderQueue=2450;}AssetDatabase.CreateAsset(m,path);return m;}
public void Execute(ExecutionResult result){var bark=Make("PineA_Bark","Bark",false);var foliage=Make("PineA_Foliage","Pine_A",true);var billboard=Make("PineA_Billboard","Pine_A_Billboard",true);AssetDatabase.SaveAssets();var s=SceneManager.GetActiveScene();var r=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).First(r=>r.enabled&&r.gameObject.activeInHierarchy&&r.name=="Pine_A_LOD0");var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TerrainDemoScene_HDRP/Prefabs/Trees/Pines/Pine_A/Pine_A.st");var original=model.GetComponentsInChildren<Renderer>(true).First(x=>x.name==r.name);result.Log("source slots="+string.Join(";",original.sharedMaterials.Select(m=>m.name)));var b=r.bounds;var go=new GameObject("__QA");var c=go.AddComponent<Camera>();c.fieldOfView=50;c.transform.position=b.center+new Vector3(b.size.y*.7f,0,-b.size.y*.8f);c.transform.LookAt(b.center);MMSequentialEvidence.Render(c,"Validation/VisualRefinement/pineA_before.png",900,900);var old=r.sharedMaterials;r.sharedMaterials=original.sharedMaterials.Select(m=>m.name.ToLowerInvariant().Contains("bark")?bark:foliage).ToArray();MMSequentialEvidence.Render(c,"Validation/VisualRefinement/pineA_preview.png",900,900);r.sharedMaterials=old;UnityEngine.Object.DestroyImmediate(go);result.Log("Preview restored");}}
